function about(){return wrap(`<div class="two reveal"><div>${tag(t('The athlete','الرياضي'))}<h2 style="margin-top:25px">${t('Moein Abdi.\nBeyond the Name.','معین عبدی.\nوراء الاسم.').replaceAll('\n','<br>')} </h2><p class="lede">${t('Iranian MTB Cross-Country Athlete & Cycling Coach','رياضي إيراني في الدراجات الجبلية ومدرب دراجات')}</p><p class="lede">${t('Moein Abdi is an Iranian mountain bike cross-country athlete whose competitive background includes provincial and national racing. His representative reports four consecutive Khorasan Razavi provincial titles, multiple national U23 runner-up finishes, and former Iranian national-team membership.','معین عبدی رياضي إيراني في الكروس كانتري تتضمن خلفيته سباقات إقليمية ووطنية. ويفيد ممثله بحصوله على أربعة ألقاب إقليمية متتالية في خراسان رضوي ومراكز وصافة وطنية متعددة تحت ٢٣ عاماً وعضوية سابقة في المنتخب الإيراني.')}</p><p class="lede">${t('Alongside competition, he pursues cycling coaching. His public VO2 profile lists a domestic Level 3 coaching qualification, mountain cycling specialization, and an association with Davandegan Koohestan club.','إلى جانب المنافسة، يعمل في تدريب الدراجات. يدرج ملفه العام على VO2 مؤهل المستوى الثالث المحلي وتخصص الدراجات الجبلية والارتباط بنادي دوندگان کوهستان.')}</p><p class="lede">${t('He is exploring international racing, coaching, and partnership opportunities, particularly within the cycling community of the United Arab Emirates.','يستكشف فرصاً دولية في السباقات والتدريب والشراكات، خاصة في مجتمع الدراجات بدولة الإمارات.')}</p><a class="text-link spaced" href="/downloads/moein-abdi-athletic-cv.pdf" download>${t('Download Athletic CV ↓','تنزيل السيرة الرياضية ↓')}</a></div>${photo()}</div>`)+wrap(`${sectionTop(t('A Career in Development.','مسيرة تتطور باستمرار.'),t('Career background','الخلفية المهنية'))}<div class="accordion">${[
[t('Provincial competition','المنافسات الإقليمية'),t('Four consecutive Khorasan Razavi provincial championship titles are athlete-reported. Dates and individual event records have not yet been provided.','أربعة ألقاب متتالية في خراسان رضوي وفق إفادة الرياضي. لم تُقدّم بعد تواريخ وسجلات الأحداث الفردية.')],
[t('National competition','المنافسات الوطنية'),t('Multiple national U23 runner-up finishes are athlete-reported. These are not national championship victories.','مراكز وصافة وطنية متعددة تحت ٢٣ عاماً وفق إفادة الرياضي. وهي ليست ألقاب بطولة وطنية.')],
[t('National-team experience','تجربة المنتخب'),t('Former membership and training-camp participation are athlete-reported. A dated history will be added when supporting records are available.','عضوية سابقة ومشاركة في معسكرات وفق إفادة الرياضي. سيُضاف التاريخ المفصل عند توفر السجلات.')],
[t('Coaching & future ambitions','التدريب والطموحات'),t('Coaching credentials are listed by VO2. Current team affiliation, international availability, and detailed career dates should be confirmed directly.','المؤهلات التدريبية مدرجة على VO2. يجب تأكيد الفريق الحالي والتوافر الدولي وتواريخ المسيرة مباشرة.')]
].map(([a,b])=>`<details><summary>${a}</summary><p>${b}</p></details>`).join('')}</div>`,'soft')+wrap(`${sectionTop(t('A Considered Approach.','نهج مدروس.'),t('Coaching philosophy','فلسفة التدريب'))}<div class="three">${feature('◎',t('Know the Rider','فهم الرياضي'),t('Begin with individual goals, experience, and circumstances.','ابدأ بالأهداف الفردية والخبرة والظروف.'))}${feature('↗',t('Build With Purpose','البناء بهدف'),t('Make consistency and technical practice part of the process.','اجعل الاستمرارية والممارسة التقنية جزءاً من العملية.'))}${feature('◷',t('Keep Learning','مواصلة التعلم'),t('Review the work and adapt to support sustainable progress.','راجع العمل وتكيّف لدعم التقدم المستدام.'))}</div><div class="note">${t('Biography prepared from supplied project information and the public VO2 profile. Athlete approval and documentary verification remain part of final editorial review.','أُعدت السيرة من معلومات المشروع وملف VO2 العام. تظل موافقة الرياضي والتحقق من المستندات جزءاً من المراجعة النهائية.')}</div>`)}
const achievementsData=[{type:'provincial',num:'4×',title:['Consecutive Provincial Titles','ألقاب إقليمية متتالية'],copy:['Khorasan Razavi, Iran. Four consecutive provincial championship titles reported by the athlete’s representative. Individual years and official result sheets have not been supplied.','خراسان رضوي، إيران. أربعة ألقاب إقليمية متتالية وفق ممثل الرياضي. لم تُقدم السنوات الفردية أو أوراق النتائج الرسمية.']},{type:'national',num:'U23',title:['National Runner-Up Finishes','مراكز وصافة وطنية'],copy:['Multiple Iranian national runner-up finishes in the U23 category, as reported for this project. Exact events, dates, and finishing fields await documentary records.','مراكز وصافة وطنية متعددة في فئة تحت ٢٣ عاماً وفق معلومات المشروع. تنتظر الأحداث والتواريخ وحقول النتائج الدقيقة سجلات موثقة.']}];
function achievementList(filter='all'){const rows=achievementsData.filter(a=>filter==='all'||a.type===filter);return rows.length?rows.map(a=>`<article class="achievement"><span class="number">${a.num}</span><div><h3>${t(a.title)}</h3><p>${t(a.copy)}</p></div>${badge()}</article>`).join(''):`<div class="empty"><h3>${t('No documented records in this category yet.','لا توجد سجلات موثقة في هذه الفئة بعد.')}</h3><p>${t('Only supplied race records will be included.','ستُدرج فقط سجلات السباقات المقدمة.')}</p></div>`}
function achievements(){return wrap(`${sectionTop(t('The Competitive Background.','الخلفية التنافسية.'),t('Reported achievements','الإنجازات المبلغ عنها'))}<div class="filters" aria-label="${t('Filter achievements','تصفية الإنجازات')}">${[['all','All','الكل'],['provincial','Provincial','إقليمي'],['national','National','وطني']].map(([id,en,aa])=>`<button class="filter" aria-pressed="${id==='all'}" data-filter="${id}">${t(en,aa)}</button>`).join('')}</div><div id="achievement-list" aria-live="polite">${achievementList()}</div><div class="note">${t('Championship results and national-team experience are separate categories. No national championship victory, international result, or active UCI ranking is claimed.','نتائج البطولات وتجربة المنتخب فئتان منفصلتان. لا يُدّعى تحقيق بطولة وطنية أو نتيجة دولية أو تصنيف UCI نشط.')}</div>`)+wrap(`${sectionTop(t('Experience Beyond Results.','خبرة تتجاوز النتائج.'),t('National team','المنتخب الوطني'))}<div class="two"><div><h3>${t('Former Iranian National Team Member','عضو سابق في المنتخب الإيراني')}</h3><p class="lede">${t('Membership and training-camp participation are athlete-reported. This background is presented as development experience, not as a championship title.','العضوية والمشاركة في معسكرات التدريب وفق إفادة الرياضي. تُعرض هذه الخلفية كخبرة تطويرية، لا كلقب بطولة.')}</p>${link('/national-team',t('Explore Team Experience →','استكشف تجربة المنتخب ←'),'text-link spaced')}</div><div class="empty"><h3>${t('A Growing Results Archive.','سجل نتائج يتطور.')}</h3><p>${t('Individual race pages and year filters will appear as dated, supported records are added. XCM records will only be shown if documented.','ستظهر صفحات السباقات وتصفية السنوات عند إضافة سجلات مؤرخة ومدعومة. لن تُعرض نتائج XCM إلا بتوثيق.')}</p>${link('/contact?topic=team',t('Request Racing Information →','اطلب معلومات السباقات ←'),'text-link')}</div></div>`,'soft')}
function racing(){const facts=[[t('Full name','الاسم الكامل'),'Moein Abdi'],[t('Nationality','الجنسية'),t('Iranian','إيراني')],[t('Primary discipline','التخصص الأساسي'),'MTB XC / XCO'],[t('Competitive background','الخلفية التنافسية'),t('Provincial & national competition','منافسات إقليمية ووطنية')],[t('Race category in reported results','فئة النتائج المبلغ عنها'),'U23'],[t('National-team background','خلفية المنتخب'),t('Former member · Athlete-reported','عضو سابق · وفق إفادة الرياضي')],[t('Coaching qualification','مؤهل التدريب'),t('Domestic Level 3 · VO2','المستوى الثالث المحلي · VO2')],[t('Career interest','التوجه المهني'),t('UAE & international opportunities','فرص الإمارات والفرص الدولية')]];return wrap(`${sectionTop(t('The Athlete at a Glance.','الرياضي في لمحة.'),t('Recruitment profile','ملف التوظيف الرياضي'))}<dl class="fact-list reveal">${facts.map(([a,b])=>`<div class="fact"><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><div class="two spaced"><a class="pill black" href="/downloads/moein-abdi-athletic-cv.pdf" download>${t('Download Athletic CV','تنزيل السيرة الرياضية')}<span class="arrow">↓</span></a>${pill('/contact?topic=team',t('Discuss Team Opportunities','ناقش فرص الانضمام للفرق'))}</div>`)+wrap(`${sectionTop(t('Competitive Experience.','الخبرة التنافسية.'),t('Racing record','سجل السباقات'))}${achievementList()}${link('/achievements',t('View the Racing Archive →','عرض سجل المنافسات ←'),'text-link spaced')}`,'soft')+wrap(`<div class="two"><div><h2>${t('A Clear View of Performance.','رؤية واضحة للأداء.')}</h2><p class="lede">${t('No estimated FTP, W/kg, VO2max, UCI ranking, or international race results are published. Evaluation data can be added when actual tests and official records are available.','لا تُنشر تقديرات FTP أو واط/كغ أو VO2max أو تصنيف UCI أو نتائج دولية. يمكن إضافة بيانات التقييم عند توفر اختبارات فعلية وسجلات رسمية.')}</p>${link('/performance',t('View Performance Profile →','عرض ملف الأداء ←'),'text-link spaced')}</div><div class="empty"><h3>${t('Recruitment Enquiries','استفسارات الفرق')}</h3><p>${t('Contact Moein to discuss current availability, team affiliation, supporting documents, and the next step in a professional evaluation.','تواصل مع معین لمناقشة التوافر الحالي والفريق والمستندات والخطوة التالية في التقييم المهني.')}</p>${pill('/contact?topic=team',t('Make an Enquiry','أرسل استفساراً'))}</div></div>`)}
function national(){return wrap(`<div class="two reveal"><div>${tag(t('Athlete-reported experience','خبرة وفق إفادة الرياضي'))}<h2 style="margin-top:25px">${t('Development at\na Higher Level.','تطور على\nمستوى أعلى.').replaceAll('\n','<br>')}</h2><p class="lede">${t('Experience within Iran’s national cycling program has been an important part of Moein Abdi’s competitive development, providing exposure to structured training environments and high-level athletic preparation.','كانت التجربة ضمن برنامج المنتخب الإيراني للدراجات جزءاً مهماً من تطور معین عبدی التنافسي، وأتاحت التعرف على بيئات تدريب منظمة وإعداد رياضي متقدم.')}</p><p class="lede">${t('Former membership and participation in national-team training camps have been reported by the athlete’s representative. Dates, locations, team category, and supporting documents are being assembled before a detailed history is published.','أفاد ممثل الرياضي بالعضوية السابقة والمشاركة في معسكرات المنتخب. يجري جمع التواريخ والمواقع وفئة الفريق والمستندات قبل نشر تاريخ مفصل.')}</p>${pill('/contact?topic=team',t('Discuss Team Opportunities','ناقش فرص الفرق'))}</div><div class="empty"><span class="star" style="font-size:60px">✦</span><h3 style="margin-top:30px">${t('Experience, Precisely Presented.','خبرة تُعرض بدقة.')}</h3><p>${t('National-team membership is distinct from a national championship victory, international race participation, current selection, or UCI ranking points.','عضوية المنتخب تختلف عن الفوز ببطولة وطنية أو المشاركة في سباق دولي أو الاختيار الحالي أو نقاط تصنيف UCI.')}</p>${link('/racing',t('Explore Racing Profile →','استكشف الملف الرياضي ←'),'text-link')}</div></div>`)+wrap(`${sectionTop(t('The Complete Picture.','الصورة الكاملة.'),t('Racing & development','السباقات والتطور'))}<div class="three">${feature('◎',t('Team Background','خلفية المنتخب'),t('Former national-team membership, reported by the athlete.','عضوية سابقة في المنتخب وفق إفادة الرياضي.'))}${feature('▧',t('Training Camps','معسكرات التدريب'),t('Participation reported; dated records are not yet published.','مشاركة مُبلغ عنها؛ لم تُنشر سجلات مؤرخة بعد.'))}${feature('↗',t('Future Opportunities','الفرص المستقبلية'),t('Open to conversations about international development and team opportunities.','يرحب بالحوار حول التطور الدولي وفرص الفرق.'))}</div>`,'soft')}
function performance(){return wrap(`${sectionTop(t('The Demands of XC.','متطلبات الكروس كانتري.'),t('Performance framework','إطار الأداء'))}<div class="feature-grid reveal">${feature('◷',t('Endurance Development','تطوير التحمل'),t('The sustained effort and repeatability required by changing terrain and race intensity.','الجهد المستدام والقدرة على التكرار لمتطلبات التضاريس والشدة المتغيرة.'))}${feature('⌁',t('Technical XC Skills','مهارات XC التقنية'),t('Line choice, control, cornering, and handling appropriate to the demands of the trail.','اختيار المسار والتحكم والانعطاف والمهارات المناسبة لمتطلبات الطريق.'))}${feature('↗',t('Climbing Capabilities','قدرات الصعود'),t('Pacing, traction, and efficient technique through demanding climbs.','توزيع الجهد والتماسك والتقنية الفعالة في الصعود الصعب.'))}${feature('◎',t('Training Methodology','منهجية التدريب'),t('A considered balance of preparation, practice, review, and recovery.','توازن مدروس بين الإعداد والممارسة والمراجعة والتعافي.'))}</div>`)+wrap(`<div class="two"><div><h2>${t('Evidence Before Estimates.','الأدلة قبل التقديرات.')}</h2><p class="lede">${t('Physiological metrics and physical-profile data are not yet available for publication. We do not fill that space with estimated figures.','المقاييس الفسيولوجية وبيانات الملف البدني غير متاحة للنشر بعد. لا نعوض ذلك بأرقام تقديرية.')}</p>${pill('/contact?topic=team',t('Request an Evaluation Discussion','اطلب مناقشة التقييم'))}</div><div class="empty"><h3>${t('Professional Evaluation','التقييم المهني')}</h3><p>${t('FTP, W/kg, VO2max, maximum aerobic power, training volume, and race power data will be published only with real test records and relevant context.','لن تُنشر بيانات FTP وواط/كغ وVO2max والقدرة الهوائية وحجم التدريب وقدرة السباق إلا مع سجلات اختبار حقيقية وسياق مناسب.')}</p><small>${t('For sporting directors, performance coaches, and team managers.','للمديرين الرياضيين ومدربي الأداء ومديري الفرق.')}</small></div></div>`,'soft')}
function coaching(){return wrap(`<div class="two"><div><h2>${t('Racing Experience.\nA Coaching Perspective.','خبرة سباقات.\nورؤية تدريبية.').replaceAll('\n','<br>')}</h2><p class="lede">${t('Moein brings a competitive cross-country background to cycling coaching, with a focus on practical skills and purposeful preparation. Start with a conversation about what you want to improve.','يستفيد معین من خلفيته التنافسية في الكروس كانتري في تدريب الدراجات، مع التركيز على المهارات العملية والإعداد الهادف. ابدأ بحوار حول ما تريد تطويره.')}</p><div class="fact"><dt>${t('Public coaching profile','ملف التدريب العام')}</dt><dd>${t('Iranian domestic Level 3 qualification','مؤهل تدريب إيراني محلي من المستوى الثالث')}</dd></div><p class="selection-note">${t('Listed on VO2: mountain cycling, Khorasan Razavi, Davandegan Koohestan club.','مدرج على VO2: الدراجات الجبلية، خراسان رضوي، نادي دوندگان کوهستان.')}</p><a class="text-link spaced" href="${vo2}" target="_blank" rel="noopener">${t('View the Source Profile ↗','عرض الملف المصدر ↗')}</a></div>${photo()}</div>`)+wrap(`${sectionTop(t('A Plan Starts With You.','الخطة تبدأ بك.'),t('The method','المنهج'))}${process()}`,'soft')+wrap(`${sectionTop(t('Explore Coaching.','استكشف التدريب.'),t('Coaching options','خيارات التدريب'))}${plans()}`)+wrap(`${sectionTop(t('Before You Begin.','قبل البداية.'),t('Questions & answers','أسئلة وأجوبة'))}${faq()}`,'soft')}
function planPage(){return wrap(`${sectionTop(t('Choose a Starting Point.','اختر نقطة البداية.'),t('Consultation-led programs','برامج تبدأ باستشارة'))}${plans()}<p class="selection-note">${t('Program names describe areas for discussion. Pricing, delivery format, duration, and availability are not yet published and must be agreed directly.','أسماء البرامج تصف مجالات المناقشة. لم تُنشر الأسعار أو طريقة التنفيذ أو المدة أو التوافر بعد، ويجب الاتفاق عليها مباشرة.')}</p>`)+wrap(`${sectionTop(t('What We’ll Discuss.','ما سنناقشه.'),t('Your consultation','استشارتك'))}<div class="three">${feature('◎',t('Your Starting Point','نقطة البداية'),t('Current riding experience, goals, and available training time.','خبرتك الحالية وأهدافك والوقت المتاح للتدريب.'))}${feature('▧',t('The Right Support','الدعم المناسب'),t('Technical practice, structured preparation, and a suitable review format.','الممارسة التقنية والإعداد المنظم وشكل المراجعة المناسب.'))}${feature('◷',t('A Clear Agreement','اتفاق واضح'),t('Scope, fees, communication, and cancellation terms before any payment.','النطاق والرسوم والتواصل وشروط الإلغاء قبل الدفع.'))}</div>`,'soft')+wrap(`${sectionTop(t('Questions Before Coaching.','أسئلة قبل التدريب.'),t('Coaching FAQ','أسئلة التدريب'))}${faq()}`)}
function form(book=false){return `<form class="form" id="enquiry-form"><input class="honeypot" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="two"><label class="field">${t('Your name','اسمك')}<input name="name" autocomplete="name" required minlength="2" maxlength="100"></label><label class="field">${t('Email address','البريد الإلكتروني')}<input name="email" type="email" autocomplete="email" required maxlength="180" dir="ltr"></label></div><label class="field">${t('What would you like to discuss?','ما الذي ترغب في مناقشته؟')}<select name="topic" required>${[['coaching','Cycling coaching','تدريب الدراجات'],['team','Team opportunities','فرص الفرق'],['sponsorship','Sponsorship & partnerships','الرعاية والشراكات'],['media','Media enquiry','استفسار إعلامي'],['general','General enquiry','استفسار عام']].map(([value,en,aa])=>`<option value="${value}">${t(en,aa)}</option>`).join('')}</select></label>${book?`<div class="two"><label class="field">${t('Riding experience','خبرة ركوب الدراجات')}<select name="experience"><option value="beginner">${t('Building my foundations','أبني أساسياتي')}</option><option value="recreational">${t('Regular recreational rider','هاوٍ يمارس بانتظام')}</option><option value="competitive">${t('Competitive rider','رياضي منافس')}</option></select></label><label class="field">${t('Country / time zone','البلد / المنطقة الزمنية')}<input name="region" maxlength="100" autocomplete="country-name"></label></div>`:''}<label class="field">${t('Your message','رسالتك')}<textarea name="message" required minlength="20" maxlength="3000" placeholder="${book?t('Tell us about your riding, goals, and preferred coaching format. Please do not include medical records.','أخبرنا عن خبرتك وأهدافك وطريقة التدريب المفضلة. يرجى عدم إدراج سجلات طبية.'):t('A little context helps us understand your enquiry.','يساعدنا بعض السياق على فهم استفسارك.')}"></textarea></label><label class="check"><input type="checkbox" name="consent" required><span>${t('I agree to the use of my details to respond to this enquiry, as described in the','أوافق على استخدام بياناتي للرد على هذا الاستفسار وفقاً لـ')} ${link('/privacy',t('Privacy Policy','سياسة الخصوصية'),'text-link')}. ${t('Please do not submit sensitive medical information.','يرجى عدم إرسال معلومات طبية حساسة.')}</span></label><button type="submit" class="pill black">${book?t('Request a Consultation','اطلب استشارة'):t('Send Enquiry','أرسل الاستفسار')}<span class="arrow" aria-hidden="true">→</span></button><p class="form-status" role="status" aria-live="polite"></p><p class="selection-note">${t('No payment is collected. A request is not a confirmed booking.','لا يتم تحصيل أي دفع. إرسال الطلب لا يعني تأكيد الحجز.')}</p></form>`}
function contact(book=false){return wrap(`<div class="contact-layout"><div>${tag(t('Get in touch','تواصل'))}<h2 style="font-size:40px;margin-top:22px">${book?t('Let’s Understand\nYour Goals.','لنفهم\nأهدافك.').replaceAll('\n','<br>'):t('A Good Conversation\nStarts Here.','حوار جيد\nيبدأ هنا.').replaceAll('\n','<br>')}</h2><p class="lede">${book?t('Share your experience and the direction you want to take. Moein can then discuss suitability, format, and next steps with you.','شارك خبرتك والاتجاه الذي تريد الوصول إليه. بعدها يمكن لمعین مناقشة الملاءمة والطريقة والخطوات القادمة.'):t('Whether you represent a team, a brand, or your own next chapter on the bike, tell us what you have in mind.','سواء كنت تمثل فريقاً أو علامة تجارية أو تسعى لخطوتك القادمة في ركوب الدراجات، أخبرنا بما تفكر فيه.')}</p><div class="contact-info"><div class="contact-card"><span class="icon" aria-hidden="true">◎</span><div><h3>${t('International Ambition','طموح دولي')}</h3><p>${t('Iran · UAE & international enquiries welcome','إيران · نرحب باستفسارات الإمارات والعالم')}</p></div></div><a class="contact-card" href="${vo2}" target="_blank" rel="noopener"><span class="icon" aria-hidden="true">↗</span><div><h3>${t('Professional Coaching Profile','ملف التدريب المهني')}</h3><p>${t('View Moein’s public profile on VO2','عرض ملف معین العام على VO2')}</p></div></a></div><p class="selection-note">${t('Direct phone and email details will appear once supplied and approved.','ستظهر بيانات الهاتف والبريد المباشرة عند تقديمها واعتمادها.')}</p></div>${form(book)}</div>`,'soft')}
function sponsorship(){return wrap(`<div class="two"><div><h2>${t('A Partnership With\na Real Story.','شراكة ذات\nقصة حقيقية.').replaceAll('\n','<br>')}</h2><p class="lede">${t('Moein is exploring conversations with cycling brands, equipment manufacturers, sports organizations, and teams that share an interest in athlete development and the XC community.','يستكشف معین الحوار مع علامات الدراجات ومصنعي المعدات والمؤسسات الرياضية والفرق المهتمة بتطور الرياضي ومجتمع XC.')}</p><p class="lede">${t('Each partnership should begin with a clear discussion of objectives, appropriate deliverables, rights, and how success will be evaluated. Audience size, reach, and commercial outcomes are not assumed.','ينبغي أن تبدأ كل شراكة بنقاش واضح للأهداف والمخرجات المناسبة والحقوق وكيفية تقييم النجاح. لا يتم افتراض حجم جمهور أو مدى وصول أو نتائج تجارية.')}</p><a class="pill black spaced" href="/downloads/moein-abdi-media-kit.pdf" download>${t('Download Media Kit','تنزيل الملف الإعلامي')}<span class="arrow">↓</span></a></div>${photo()}</div>`)+wrap(`${sectionTop(t('Ways to Work Together.','طرق للعمل معاً.'),t('Partnership conversations','حوارات الشراكة'))}<div class="three">${feature('◈',t('Equipment Partnerships','شراكات المعدات'),t('Discuss product support, athlete feedback, and relevant cycling equipment.','ناقش دعم المنتجات وملاحظات الرياضي ومعدات الدراجات المناسبة.'))}${feature('↗',t('Athlete Development','تطوير الرياضي'),t('Explore support for structured preparation and appropriate racing opportunities.','استكشف دعم الإعداد المنظم وفرص السباقات المناسبة.'))}${feature('◎',t('Community & Content','المجتمع والمحتوى'),t('Consider authentic content and participation aligned with shared objectives.','ناقش المحتوى الحقيقي والمشاركة بما يتوافق مع الأهداف المشتركة.'))}</div>`,'soft')+wrap(`<div class="two"><div><h2>${t('Let’s Define\nthe Right Fit.','لنحدد\nالشراكة المناسبة.').replaceAll('\n','<br>')}</h2><p class="lede">${t('No sponsor relationship, media audience, or commercial commitment is implied by this page. Proposed partnerships are individually discussed and agreed.','لا تعني هذه الصفحة وجود علاقة رعاية أو جمهور إعلامي أو التزام تجاري. تتم مناقشة الشراكات المقترحة والاتفاق عليها فردياً.')}</p></div><div class="empty"><h3>${t('Start With a Conversation.','ابدأ بحوار.')}</h3><p>${t('Tell us about your organization, the opportunity, and what a meaningful collaboration looks like to you.','أخبرنا عن مؤسستك والفرصة وما الذي تعنيه لك شراكة ذات قيمة.')}</p>${pill('/contact?topic=sponsorship',t('Discuss a Partnership','ناقش شراكة'))}</div></div>`)}
function gallery(){return wrap(`${sectionTop(t('Authentic, Always.','الحقيقة دائماً.'),t('Photography','التصوير'))}<div class="gallery-grid"><figure style="margin:0"><button class="gallery-item" data-gallery aria-label="${t('Open photograph of Moein Abdi','افتح صورة معین عبدی')}">${photo()}<span class="text-link" style="margin-top:15px">${t('View Photograph ↗','عرض الصورة ↗')}</span></button><figcaption class="selection-note">${t('Moein Abdi · Public VO2 coaching profile. Event and date not established.','معین عبدی · ملف التدريب العام على VO2. لم يتم تحديد الحدث والتاريخ.')}</figcaption></figure><div class="stack"><div class="empty"><span class="star" style="font-size:55px">✦</span><h3 style="margin-top:25px">${t('More of the Journey,\nAs It Happens.','المزيد من المسيرة،\nكما تحدث.').replaceAll('\n','<br>')}</h3><p>${t('Race action, training camps, coaching sessions, and behind-the-scenes images will be added when Moein’s original photography is supplied.','ستُضاف صور السباقات والمعسكرات والجلسات التدريبية والكواليس عند تقديم الصور الأصلية لمعین.')}</p>${link('/contact?topic=media',t('Media Enquiries →','استفسارات إعلامية ←'),'text-link')}</div><p class="selection-note">${t('Photographs of other athletes are not presented as Moein. This provisional image is sourced from his public profile and awaits final usage approval.','لا تُعرض صور رياضيين آخرين على أنها لمعین. هذه الصورة المؤقتة مأخوذة من ملفه العام وتنتظر اعتماد الاستخدام النهائي.')}</p></div></div><dialog id="photo-dialog"><button class="close" aria-label="${t('Close photograph','أغلق الصورة')}">×</button><img src="/assets/moein-portrait.webp" alt="${t('Moein Abdi holding a trophy','معین عبدی يحمل كأساً')}"><p>${t('Source: VO2 public profile. Event and date not established.','المصدر: ملف VO2 العام. الحدث والتاريخ غير محددين.')}</p></dialog>`)}
function journal(){return wrap(`${sectionTop(t('Read. Reflect. Ride.','اقرأ. تأمل. وانطلق.'),t('Editorial guides','أدلة تحريرية'))}${journals()}<p class="selection-note">${t('General editorial guides prepared for this website. These are not personal quotations or clinical advice from Moein.','أدلة تحريرية عامة أُعدت لهذا الموقع. ليست اقتباسات شخصية أو نصائح سريرية من معین.')}</p>`)}
function article(a){return wrap(`<article class="body-copy" style="margin:auto"><div class="article-art">${art(articles.indexOf(a))}</div><p class="selection-note">${t('Editorial guide · General educational content','دليل تحريري · محتوى تثقيفي عام')}</p>${a.body.map((text,i)=>i%2===0?`<h2>${t(text)}</h2>`:`<p>${t(text)}</p>`).join('')}${link('/journal',t('← Back to Journal','العودة للمقالات →'),'text-link spaced')}</article>`)}
function legal(which){const data={privacy:[
[t('Information you choose to share','المعلومات التي تختار مشاركتها'),t('Enquiry forms collect your name, email, chosen subject, and message so that your request can be reviewed and answered. Coaching enquiries can also include your riding experience and country or time zone. Do not include medical records or other sensitive information.','تجمع نماذج الاستفسار الاسم والبريد والموضوع والرسالة لمراجعة طلبك والرد عليه. قد تتضمن استفسارات التدريب خبرتك وبلدك أو منطقتك الزمنية. لا ترسل سجلات طبية أو معلومات حساسة.')],
[t('Storage and retention','التخزين والاحتفاظ'),t('Submitted enquiries are stored securely for up to 90 days for follow-up and then expire. They are accessible only to the site administrator. The site does not sell enquiry data or submit it to advertising platforms.','تُحفظ الاستفسارات بأمان لمدة تصل إلى ٩٠ يوماً للمتابعة ثم تنتهي صلاحيتها. لا يصل إليها إلا مسؤول الموقع. لا يبيع الموقع بيانات الاستفسارات ولا يرسلها إلى منصات الإعلان.')],
[t('Your choices','خياراتك'),t('Use the contact form to request access, correction, or deletion of an earlier enquiry. Include only the email used for that enquiry and the nature of your request; identity may need to be confirmed before disclosure.','استخدم نموذج التواصل لطلب الوصول إلى استفسار سابق أو تصحيحه أو حذفه. أدرج البريد المستخدم وطبيعة الطلب فقط؛ قد يلزم تأكيد الهوية قبل الإفصاح.')],
[t('Cookies and hosting','ملفات الارتباط والاستضافة'),t('No advertising analytics are installed. The hosting platform may use necessary authentication cookies and infrastructure security logs. External profile links are optional and governed by their own providers’ policies.','لا توجد أدوات تحليلات إعلانية. قد تستخدم منصة الاستضافة ملفات ارتباط ضرورية لتسجيل الدخول وسجلات أمان البنية التحتية. روابط الملفات الخارجية اختيارية وتخضع لسياسات مقدميها.')]],
terms:[
[t('Using this website','استخدام الموقع'),t('This website introduces Moein Abdi’s athletic background, coaching enquiries, and partnership opportunities. Content is provided for information and does not constitute a contract for coaching, sponsorship, or team membership.','يقدم هذا الموقع خلفية معین عبدی الرياضية واستفسارات التدريب وفرص الشراكات. المحتوى للمعلومات ولا يُعد عقد تدريب أو رعاية أو عضوية فريق.')],
[t('Accuracy and credentials','الدقة والمؤهلات'),t('Athlete-reported achievements are labelled accordingly. Historical national-team experience does not establish current selection, a championship victory, international participation, or active UCI ranking. Supporting records should be requested for professional due diligence.','تُميز الإنجازات وفق إفادة الرياضي بوضوح. لا تثبت تجربة المنتخب السابقة الاختيار الحالي أو الفوز ببطولة أو المشاركة الدولية أو تصنيف UCI نشطاً. ينبغي طلب السجلات للتحقق المهني.')],
[t('Content and media','المحتوى والوسائط'),t('Site text, photography, and downloadable documents may not be used to imply endorsement or an agreed partnership. Contact the site for media permissions. The VO2 profile photograph retains its original context and is provisionally attributed.','لا يجوز استخدام النصوص والصور والمستندات للإيحاء بتأييد أو شراكة متفق عليها. تواصل لطلب أذونات الوسائط. تحتفظ صورة ملف VO2 بسياقها الأصلي مع نسبتها مؤقتاً للمصدر.')],
[t('Separate agreements','اتفاقيات مستقلة'),t('Any coaching or commercial work requires a separate agreement covering scope, availability, fees, rights, and applicable terms. No guaranteed sporting or financial outcomes are offered.','يتطلب أي عمل تدريبي أو تجاري اتفاقاً منفصلاً يحدد النطاق والتوافر والرسوم والحقوق والشروط. لا تُقدم ضمانات لنتائج رياضية أو مالية.')]],
'coaching-policies':[
[t('Consultation requests','طلبات الاستشارة'),t('Submitting a request does not reserve a session. Availability, suitability, location or online format, and communication arrangements must be confirmed directly.','إرسال الطلب لا يحجز جلسة. يجب تأكيد التوافر والملاءمة والمكان أو التنفيذ عبر الإنترنت وترتيبات التواصل مباشرة.')],
[t('Fees, changes, and cancellation','الرسوم والتغييرات والإلغاء'),t('Fees are quoted individually. Before any payment, the parties must agree the service scope, duration, payment method, cancellation or rescheduling rules, and any applicable refund terms. This website does not process payments.','تُحدد الرسوم فردياً. قبل الدفع يجب الاتفاق على نطاق الخدمة ومدتها وطريقة الدفع وقواعد الإلغاء أو إعادة الجدولة وأي شروط استرداد. لا يعالج الموقع المدفوعات.')],
[t('Health and safety','الصحة والسلامة'),t('Riders are responsible for suitable equipment and safe participation. Discuss health concerns with a qualified healthcare professional. Coaching is not a substitute for medical advice, injury treatment, or clinical nutrition services.','يتحمل الراكب مسؤولية المعدات المناسبة والمشاركة الآمنة. ناقش المخاوف الصحية مع مختص مؤهل. التدريب ليس بديلاً عن النصيحة الطبية أو علاج الإصابات أو التغذية السريرية.')],
[t('Expectations','التوقعات'),t('Progress depends on individual circumstances and cannot be guaranteed. Coaching should be adapted through communication, review, and appropriate recovery.','يعتمد التقدم على الظروف الفردية ولا يمكن ضمانه. ينبغي تكييف التدريب بالتواصل والمراجعة والتعافي المناسب.')]]};return wrap(`<div class="body-copy" style="margin:auto">${(data[which]||[]).map(([a,b])=>`<h2>${a}</h2><p>${b}</p>`).join('')}${link('/contact',t('Contact about this policy →','تواصل بخصوص هذه السياسة ←'),'text-link spaced')}</div>`)}
function admin(){return wrap(`<div id="admin-root"><div class="empty"><span class="lock-icon" aria-hidden="true">⊡</span><h2>${t('Protected Athlete Workspace.','مساحة الرياضي المحمية.')}</h2><p>${t('Administrative access requires an authorized owner account. Athlete credentials, unpublished records, and enquiries are never included in public page data.','يتطلب الوصول الإداري حساب مالك معتمداً. لا تُدرج اعتمادات الرياضي والسجلات غير المنشورة والاستفسارات في بيانات الصفحات العامة.')}</p><button class="pill black" id="admin-load">${t('Open Secure Workspace','افتح المساحة الآمنة')}<span class="arrow">→</span></button><p class="form-status" id="admin-status" role="status"></p></div></div>`)}
