if(!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const tabCopy=[t('Build confidence through deliberate technical practice. Discuss cornering, line choice, climbing, and control in a coaching approach matched to your experience.','ابنِ الثقة بالممارسة التقنية الواعية. ناقش الانعطاف واختيار المسار والصعود والتحكم ضمن نهج يناسب خبرتك.'),t('Give every session a purpose. Discuss a training direction that fits your current riding, available time, recovery, and goals.','امنح كل حصة هدفاً. ناقش اتجاهاً تدريبياً يناسب خبرتك الحالية ووقتك وتعافيك وأهدافك.'),t('Prepare with the demands of cross-country in mind. Explore pacing, technical readiness, and an appropriate approach to your next competitive goal.','استعد وفق متطلبات الكروس كانتري. ناقش توزيع الجهد والجاهزية التقنية والنهج المناسب لهدفك التنافسي القادم.')];
function selectTab(b){document.querySelectorAll('[data-tab]').forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});document.getElementById('tab-copy').textContent=tabCopy[+b.dataset.tab];document.getElementById('focus-panel').setAttribute('aria-labelledby',b.id)}
document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>selectTab(b);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.indexOf(b),n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[n]);tabs[n].focus()}}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('achievement-list').innerHTML=achievementList(b.dataset.filter)}));
