const enquiry=document.getElementById('enquiry-form');if(enquiry){const params=new URLSearchParams(location.search);if(params.has('topic')&&['coaching','team','sponsorship','media','general'].includes(params.get('topic')))enquiry.elements.topic.value=params.get('topic');if(params.has('plan'))enquiry.elements.message.value=t('I would like to discuss the ','أود مناقشة برنامج ')+(params.get('plan')==='performance'?t('Performance Development program.','تطوير الأداء.'):t('XC Foundations program.','أساسيات الكروس كانتري.'));enquiry.addEventListener('submit',async e=>{e.preventDefault();if(!enquiry.reportValidity())return;const submit=enquiry.querySelector('[type=submit]'),status=enquiry.querySelector('.form-status');submit.disabled=true;status.className='form-status';status.textContent=t('Saving your enquiry…','جارٍ حفظ الاستفسار…');try{const data=Object.fromEntries(new FormData(enquiry));data.locale=ar?'ar':'en';const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok){const body=await response.json().catch(()=>({}));throw Error(body.error==='unavailable'?'unavailable':body.error==='rate_limited'?'rate_limited':'invalid')}location.href=url('/thank-you')}catch(err){status.classList.add('error');status.textContent=err.message==='unavailable'?t('Enquiry storage is not connected yet. Please use the VO2 profile link or try again later. Your message has not been sent.','لم يتم ربط تخزين الاستفسارات بعد. يرجى استخدام رابط VO2 أو المحاولة لاحقاً. لم تُرسل رسالتك.'):err.message==='rate_limited'?t('Please wait a few minutes before sending another enquiry.','يرجى الانتظار بضع دقائق قبل إرسال استفسار آخر.'):t('Your enquiry could not be saved. Check your details and try again.','تعذر حفظ استفسارك. راجع بياناتك وحاول مجدداً.');submit.disabled=false}})}
