async function loadAdmin(){const status=document.getElementById('admin-status');if(status)status.textContent=t('Checking access…','جارٍ التحقق من الوصول…');try{const response=await fetch('/api/admin',{cache:'no-store'});if(!response.ok){if(status)status.textContent=t('Access is restricted to the configured site administrator. Sign in with the authorized account.','الوصول مقيد بمسؤول الموقع المحدد. سجّل الدخول بالحساب المعتمد.');return}renderAdmin(await response.json())}catch{if(status)status.textContent=t('The secure workspace is unavailable in this preview.','المساحة الآمنة غير متاحة في هذا العرض.')}}
function renderAdmin(data){const c=data.credentials||{};document.getElementById('admin-root').innerHTML=`<div class="admin-grid"><aside class="admin-sidebar"><h3>${t('Athlete Workspace','مساحة الرياضي')}</h3><a href="#credentials">${t('Credentials','الاعتمادات')}</a><a href="#records">${t('Draft records','مسودات السجلات')}</a><a href="#inquiries">${t('Enquiries','الاستفسارات')}</a><a href="/signout-with-chatgpt">${t('Sign out','تسجيل الخروج')}</a></aside><div class="stack"><section class="admin-panel" id="credentials"><h2 style="font-size:32px">${t('Athlete Credentials','اعتمادات الرياضي')}</h2><p class="note">${t('UCI ID: Pending recovery. No public UCI claim is enabled.','معرّف UCI: بانتظار الاسترجاع. لا يوجد ادعاء UCI عام مفعّل.')}</p><form id="credentials-form">${[['uciId','UCI ID','معرّف UCI'],['uciProfile','UCI profile URL','رابط ملف UCI'],['licenseStatus','License status','حالة الترخيص'],['licenseYear','License year','سنة الترخيص'],['discipline','Registered discipline','التخصص المسجل'],['federation','National federation','الاتحاد الوطني'],['rankingHistory','Verified ranking history','تاريخ التصنيف الموثق'],['pointsHistory','Verified points history','تاريخ النقاط الموثق'],['internationalEntries','International race entries','المشاركات الدولية'],['resultUrls','Official result URLs','روابط النتائج الرسمية'],['documents','Verification document links','روابط مستندات التحقق'],['lastVerified','Last verification date','تاريخ آخر تحقق']].map(([key,en,aa])=>`<label class="field">${t(en,aa)}<input name="${key}" maxlength="${key==='uciId'?11:2000}" value="${esc(c[key]||'')}" ${key==='uciId'?'pattern="[0-9]{11}"':key==='lastVerified'?'type="date"':''}></label>`).join('')}<label class="field">${t('Verification state','حالة التحقق')}<select name="verification">${['missing','athlete-reported','officially-verified','historical-reconfirm'].map(v=>`<option value="${v}" ${c.verification===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><button class="pill black" type="submit">${t('Save Private Credentials','حفظ الاعتمادات الخاصة')}<span class="arrow">✓</span></button><p class="form-status" role="status"></p></form></section><section class="admin-panel" id="records"><h2 style="font-size:32px">${t('Draft Records','مسودات السجلات')}</h2><p class="selection-note">${t('Drafts are private. Publication requires a separate editorial review.','المسودات خاصة. يتطلب النشر مراجعة تحريرية منفصلة.')}</p><form id="record-form"><label class="field">${t('Record category','فئة السجل')}<select name="kind"><option value="race">${t('Race result','نتيجة سباق')}</option><option value="national-team">${t('National team / camp','منتخب / معسكر')}</option><option value="performance">${t('Performance test','اختبار أداء')}</option></select></label><label class="field">${t('Title','العنوان')}<input name="title" required maxlength="180"></label><label class="field">${t('Event date','تاريخ الحدث')}<input name="date" type="date"></label><label class="field">${t('Discipline','التخصص')}<select name="discipline"><option>XCO</option><option>XCM</option></select></label><label class="field">${t('Country / city / location','البلد / المدينة / الموقع')}<input name="location" maxlength="180"></label><label class="field">${t('Race category / team category','فئة السباق / فئة المنتخب')}<input name="category" maxlength="100"></label><div class="two"><label class="field">${t('Finishing position','المركز النهائي')}<input name="position" type="number" min="1"></label><label class="field">${t('Number of starters','عدد المشاركين')}<input name="starters" type="number" min="1"></label></div><label class="field">${t('Course distance (km)','مسافة المسار (كم)')}<input name="distance" type="number" min="0" step="0.01"></label><label class="field">${t('Official results / supporting document URL','رابط النتائج الرسمية / المستند')}<input name="source" type="url" maxlength="2000"></label><label class="field">${t('Verification state','حالة التحقق')}<select name="verification"><option value="athlete-reported">${t('Athlete-reported','وفق إفادة الرياضي')}</option><option value="officially-verified">${t('Officially verified','موثق رسمياً')}</option><option value="missing">${t('Missing information','معلومات مفقودة')}</option><option value="historical-reconfirm">${t('Historical — reconfirm','تاريخي — يحتاج تأكيداً')}</option></select></label><label class="field">${t('Notes / test data / coaching staff','ملاحظات / بيانات اختبار / طاقم تدريب')}<textarea name="notes" maxlength="5000"></textarea></label><button class="pill black" type="submit">${t('Save Draft','حفظ المسودة')}<span class="arrow">✓</span></button><p class="form-status" role="status"></p></form><div class="spaced">${(data.records||[]).map(r=>`<p><strong>${esc(r.title)}</strong> — ${esc(r.kind)} · ${esc(r.verification)} <button class="filter" data-delete-record="${esc(r.id)}">${t('Delete','حذف')}</button></p>`).join('')}</div></section><section class="admin-panel" id="inquiries"><h2 style="font-size:32px">${t('Enquiries','الاستفسارات')}</h2><button class="filter spaced" id="export-enquiries">${t('Export JSON','تصدير JSON')}</button><div class="table-wrap"><table><thead><tr><th>${t('Name','الاسم')}</th><th>${t('Email','البريد')}</th><th>${t('Subject','الموضوع')}</th><th>${t('Message','الرسالة')}</th><th>${t('Actions','الإجراءات')}</th></tr></thead><tbody>${(data.enquiries||[]).map(q=>`<tr><td>${esc(q.name)}</td><td>${esc(q.email)}</td><td>${esc(q.topic)}</td><td>${esc(q.message)}</td><td><button class="filter" data-delete="${esc(q.id)}">${t('Delete','حذف')}</button></td></tr>`).join('')}</tbody></table></div>${data.enquiries?.length?'':`<p class="selection-note">${t('No enquiries yet.','لا توجد استفسارات بعد.')}</p>`}</section></div></div>`;
async function saveAdmin(form,type){const status=form.querySelector('.form-status');const response=await fetch('/api/admin/'+type,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});status.textContent=response.ok?t('Saved privately.','تم الحفظ بشكل خاص.'):t('Could not save. Check the fields and your access.','تعذر الحفظ. راجع الحقول والصلاحيات.');if(response.ok&&type==='records')loadAdmin()}
document.getElementById('credentials-form').onsubmit=e=>{e.preventDefault();saveAdmin(e.target,'credentials')};document.getElementById('record-form').onsubmit=e=>{e.preventDefault();saveAdmin(e.target,'records')};document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(t('Delete this enquiry permanently?','حذف هذا الاستفسار نهائياً؟')))return;const r=await fetch('/api/admin/enquiries/'+b.dataset.delete,{method:'DELETE'});if(r.ok)loadAdmin()});document.querySelectorAll('[data-delete-record]').forEach(b=>b.onclick=async()=>{if(!confirm(t('Delete this draft?','حذف هذه المسودة؟')))return;const r=await fetch('/api/admin/records/'+b.dataset.deleteRecord,{method:'DELETE'});if(r.ok)loadAdmin()});document.getElementById('export-enquiries').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data.enquiries||[],null,2)],{type:'application/json'}));a.download='enquiries.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};}
